pub trait Shape { fn area(&self) -> f64; }

pub fn make_shape(kind: &str, size: f64) -> Result<Box<dyn Shape>, ShapeError> {
    match kind {
        "circle" => Ok(Box::new(Circle { r: size })),
        "square" => Ok(Box::new(Square { side: size })),
        other => Err(ShapeError::Unknown(other.to_string())),
    }
}

